#Emergência-visualização rápida{position:fixed;inset:0;z-index:9999;display:none;
      background:#000;color:#fff;overflow-y:auto;
      font-family:Inter,system-ui,sans-serif;}
    .eqv-header{position:sticky;top:0;z-index:2;
      background:rgba(0,0,0,0.92);backdrop-filter:blur(6px);
      padding:16px;display:flex;align-items:center;justify-content:space-between;
      border-bottom:1px solid rgba(255,255,255,0.08);}
    Eqv-título{font-size:12px;font-weight:900;letter-spacing:2.5px;
      color:#12A5FF;text-shadow:0 0 8px #12A5FF;text-transform:uppercase;}
    .eqv- Fechar{background:transparent;border:1.5px solid rgba(255,255,255,0.35);
      color:#fff;border-radius:20px;padding:8px 16px;font-size:11px;
      font-weight:700;letter-spacing:1px;cursor:pointer;text-transform:uppercase;
      font-family:inherit;}
    .eqv-close:hover{background:rgba(255,255,255,0.08);}
    .eqv-grid{display:flex;flex-direction:column;align-items:center;
      gap:36px;padding:20px 20px 40px;max-width:480px;margin:0 auto;}
    Cartão eqv{display:flex;flex-direction:column;align-items:center;gap:12px;width:100%;}
    Cabeçalho tipo .eqv{display:flex;align-items:center;justify-content:center;
      gap:9px;width:100%;}
    .eqv-tipo de ponto{width:13px;height:13px;border-radius:50%;flex-shrink:0;}
    Título tipo .eqv{font-size:16px;font-weight:900;letter-spacing:1.2px;
      text-transform:uppercase;text-align:center;line-height:1.25;}
    Cobertura eqv{position:relative;border-radius:30px;background:#0a1422;
      display:flex;align-items:center;justify-content:center;overflow:hidden;}
    .eqv-cover img, . eqv -cover tela{width:90%;height:90%;object-fit:contain;
      border-radius:10px;background:#fff;display:block;}
    Nome .eqv{font-size:13px;color:rgba(255,255,255,0.75);text-align:center;
      letter-spacing:0.3px;word-break:break-word;}
